import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CTZjucLO.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-mafii.md","filePath":"regulament-mafii.md"}'),t={name:"regulament-mafii.md"};function n(o,i,u,c,s,d){return a(),r("div",null,[...i[0]||(i[0]=[l('<h2 id="📜-regulament-organizatii-criminale-romana" tabindex="-1">📜 Regulament Organizații Criminale (Română) <a class="header-anchor" href="#📜-regulament-organizatii-criminale-romana" aria-label="Permalink to &quot;📜 Regulament Organizații Criminale (Română)&quot;">​</a></h2><hr><h2 id="cap-1-dispozitii-generale" tabindex="-1">CAP. 1 - DISPOZIȚII GENERALE <a class="header-anchor" href="#cap-1-dispozitii-generale" aria-label="Permalink to &quot;CAP. 1 - DISPOZIȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-obligatiile-membrilor" tabindex="-1">1.1 Obligațiile membrilor <a class="header-anchor" href="#_1-1-obligatiile-membrilor" aria-label="Permalink to &quot;1.1 Obligațiile membrilor&quot;">​</a></h3><p>Toți membrii unei organizații criminale au obligația de a respecta regulamentul serverului și regulamentul organizațiilor.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toți membrii trebuie să respecte regulamentul general al serverului.</li><li>Deciziile liderului și ale conducerii organizației sunt obligatorii.</li><li>Participarea într-o organizație presupune respectarea ierarhiei interne.</li><li>Necunoașterea regulamentului nu constituie o scuză.</li></ul><hr><h2 id="cap-2-conduita-si-comportament" tabindex="-1">CAP. 2 - CONDUITĂ ȘI COMPORTAMENT <a class="header-anchor" href="#cap-2-conduita-si-comportament" aria-label="Permalink to &quot;CAP. 2 - CONDUITĂ ȘI COMPORTAMENT&quot;">​</a></h2><h3 id="_2-1-respect-si-limbaj" tabindex="-1">2.1 Respect și limbaj <a class="header-anchor" href="#_2-1-respect-si-limbaj" aria-label="Permalink to &quot;2.1 Respect și limbaj&quot;">​</a></h3><p>Respectul dintre jucători reprezintă o obligație indiferent de situația Roleplay.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Membrii trebuie să manifeste respect față de colegi, jucători și Staff.</li><li>Limbajul ofensator și comportamentul toxic sunt interzise.</li><li>Provocările excesive fără scop Roleplay sunt interzise.</li><li>Umilirea sau ridiculizarea altor personaje după terminarea unui conflict este interzisă.</li><li>Conducerea organizației poate aplica sancțiuni interne pentru orice abatere disciplinară.</li></ul><hr><h2 id="cap-3-activitate-si-prezenta" tabindex="-1">CAP. 3 - ACTIVITATE ȘI PREZENȚĂ <a class="header-anchor" href="#cap-3-activitate-si-prezenta" aria-label="Permalink to &quot;CAP. 3 - ACTIVITATE ȘI PREZENȚĂ&quot;">​</a></h2><h3 id="_3-1-activitatea-in-organizatie" tabindex="-1">3.1 Activitatea în organizație <a class="header-anchor" href="#_3-1-activitatea-in-organizatie" aria-label="Permalink to &quot;3.1 Activitatea în organizație&quot;">​</a></h3><p>Participarea activă la viața organizației este obligatorie.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Membrii trebuie să participe la activitățile organizației.</li><li>Absențele mai mari de <strong>72 de ore</strong> fără notificare sau aprobare pot conduce la excludere.</li><li>Conducerea poate solicita prezența membrilor la activități importante.</li></ul><hr><h2 id="cap-4-controlul-teritoriilor" tabindex="-1">CAP. 4 - CONTROLUL TERITORIILOR <a class="header-anchor" href="#cap-4-controlul-teritoriilor" aria-label="Permalink to &quot;CAP. 4 - CONTROLUL TERITORIILOR&quot;">​</a></h2><h3 id="_4-1-drepturi-si-responsabilitati" tabindex="-1">4.1 Drepturi și responsabilități <a class="header-anchor" href="#_4-1-drepturi-si-responsabilitati" aria-label="Permalink to &quot;4.1 Drepturi și responsabilități&quot;">​</a></h3><p>Organizațiile au dreptul de a controla și apăra teritoriile deținute.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Organizațiile pot desfășura activități specifice pe teritoriile controlate.</li><li>Membrii trebuie să protejeze interesele organizației.</li><li>Persoanele care cooperează cu organizația nu trebuie agresate fără motiv Roleplay.</li><li>Conflictele trebuie să aibă întotdeauna o justificare logică și realistă.</li></ul><hr><h3 id="_4-2-restrictii" tabindex="-1">4.2 Restricții <a class="header-anchor" href="#_4-2-restrictii" aria-label="Permalink to &quot;4.2 Restricții&quot;">​</a></h3><p>Pentru menținerea unui Roleplay de calitate, se aplică următoarele restricții.</p><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă provocarea conflictelor fără motiv Roleplay.</li><li>Activitățile ilegale desfășurate în zone publice trebuie să respecte logica Roleplay.</li><li>Este interzisă jefuirea sau intimidarea repetată a acelorași persoane fără context Roleplay.</li></ul><hr><h2 id="cap-5-relatiile-dintre-organizatii" tabindex="-1">CAP. 5 - RELAȚIILE DINTRE ORGANIZAȚII <a class="header-anchor" href="#cap-5-relatiile-dintre-organizatii" aria-label="Permalink to &quot;CAP. 5 - RELAȚIILE DINTRE ORGANIZAȚII&quot;">​</a></h2><h3 id="_5-1-colaborari-si-aliante" tabindex="-1">5.1 Colaborări și alianțe <a class="header-anchor" href="#_5-1-colaborari-si-aliante" aria-label="Permalink to &quot;5.1 Colaborări și alianțe&quot;">​</a></h3><p>Organizațiile pot colabora doar în limitele stabilite de administrația serverului.</p><h3 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Alianțele sunt permise doar conform regulamentului.</li><li>Membrii unei organizații nu pot percepe taxe sau revendica beneficii pe teritoriul altei organizații.</li><li>O alianță nu oferă dreptul de a încălca regulamentul serverului.</li></ul><hr><h3 id="_5-2-interventii-in-conflicte" tabindex="-1">5.2 Intervenții în conflicte <a class="header-anchor" href="#_5-2-interventii-in-conflicte" aria-label="Permalink to &quot;5.2 Intervenții în conflicte&quot;">​</a></h3><p>Intervențiile în conflictele dintre organizații trebuie să respecte logica Roleplay.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Intervenția într-un conflict trebuie să aibă o justificare Roleplay clară.</li><li>Implicarea civililor în conflictele armate dintre organizații este interzisă.</li><li>Raidurile asupra instituțiilor guvernamentale sunt interzise fără aprobarea administrației.</li></ul><hr><h2 id="cap-6-comunicare" tabindex="-1">CAP. 6 - COMUNICARE <a class="header-anchor" href="#cap-6-comunicare" aria-label="Permalink to &quot;CAP. 6 - COMUNICARE&quot;">​</a></h2><h3 id="_6-1-mijloace-de-comunicare" tabindex="-1">6.1 Mijloace de comunicare <a class="header-anchor" href="#_6-1-mijloace-de-comunicare" aria-label="Permalink to &quot;6.1 Mijloace de comunicare&quot;">​</a></h3><p>Comunicarea dintre membrii organizației trebuie realizată exclusiv prin metode Roleplay.</p><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Comunicarea trebuie efectuată prin mijloace existente în joc.</li><li>Utilizarea informațiilor obținute prin Discord, stream-uri sau alte surse externe reprezintă <strong>Meta Gaming</strong> și se sancționează conform regulamentului general.</li></ul><hr><h2 id="cap-7-recrutare" tabindex="-1">CAP. 7 - RECRUTARE <a class="header-anchor" href="#cap-7-recrutare" aria-label="Permalink to &quot;CAP. 7 - RECRUTARE&quot;">​</a></h2><h3 id="_7-1-admiterea-membrilor" tabindex="-1">7.1 Admiterea membrilor <a class="header-anchor" href="#_7-1-admiterea-membrilor" aria-label="Permalink to &quot;7.1 Admiterea membrilor&quot;">​</a></h3><p>Recrutarea trebuie să fie rezultatul unui Roleplay natural.</p><h3 id="reguli-8" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-8" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Recrutarea nu poate avea loc fără un Roleplay corespunzător.</li><li>Conducerea stabilește criteriile de selecție.</li><li>Perioada de probă este cuprinsă între <strong>14 și 30 de zile</strong>.</li><li>Toate recrutările trebuie să respecte standardele de Roleplay impuse de server.</li></ul><hr><h2 id="cap-8-parasirea-organizatiei" tabindex="-1">CAP. 8 - PĂRĂSIREA ORGANIZAȚIEI <a class="header-anchor" href="#cap-8-parasirea-organizatiei" aria-label="Permalink to &quot;CAP. 8 - PĂRĂSIREA ORGANIZAȚIEI&quot;">​</a></h2><h3 id="_8-1-excluderi-si-retrageri" tabindex="-1">8.1 Excluderi și retrageri <a class="header-anchor" href="#_8-1-excluderi-si-retrageri" aria-label="Permalink to &quot;8.1 Excluderi și retrageri&quot;">​</a></h3><p>Părăsirea unei organizații produce consecințe Roleplay.</p><h3 id="reguli-9" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-9" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Liderul poate exclude orice membru care încalcă regulamentul.</li><li>Membrii trebuie să respecte consecințele Roleplay rezultate din apartenența la organizație.</li><li>În cazul aplicării unui <strong>PK</strong>, informațiile obținute în cadrul organizației nu mai pot fi utilizate ulterior.</li></ul><hr><h2 id="cap-9-sistemul-de-sanctiuni" tabindex="-1">CAP. 9 - SISTEMUL DE SANCȚIUNI <a class="header-anchor" href="#cap-9-sistemul-de-sanctiuni" aria-label="Permalink to &quot;CAP. 9 - SISTEMUL DE SANCȚIUNI&quot;">​</a></h2><h3 id="_9-1-tipuri-de-sanctiuni" tabindex="-1">9.1 Tipuri de sancțiuni <a class="header-anchor" href="#_9-1-tipuri-de-sanctiuni" aria-label="Permalink to &quot;9.1 Tipuri de sancțiuni&quot;">​</a></h3><p>În funcție de gravitatea abaterii pot fi aplicate următoarele sancțiuni.</p><h3 id="sanctiuni" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Avertisment verbal.</li><li>Avertisment intern.</li><li>Suspendare temporară.</li><li>Excludere din organizație.</li><li>Sancțiuni administrative aplicate de Staff.</li></ul><hr><h3 id="_9-2-responsabilitatea-conducerii" tabindex="-1">9.2 Responsabilitatea conducerii <a class="header-anchor" href="#_9-2-responsabilitatea-conducerii" aria-label="Permalink to &quot;9.2 Responsabilitatea conducerii&quot;">​</a></h3><p>Conducerea organizației răspunde de disciplina membrilor.</p><h3 id="reguli-10" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-10" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Liderii sunt responsabili pentru organizarea și coordonarea organizației.</li><li>Conducerea trebuie să asigure respectarea regulamentului.</li><li>Încălcarea repetată a regulamentului poate conduce la sancționarea întregii organizații.</li></ul><hr><h2 id="cap-10-dispozitii-finale" tabindex="-1">CAP. 10 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-10-dispozitii-finale" aria-label="Permalink to &quot;CAP. 10 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_10-1-aplicarea-regulamentului" tabindex="-1">10.1 Aplicarea regulamentului <a class="header-anchor" href="#_10-1-aplicarea-regulamentului" aria-label="Permalink to &quot;10.1 Aplicarea regulamentului&quot;">​</a></h3><p>Administrația <strong>Legacy Of CLT Roleplay</strong> își rezervă dreptul de a modifica prezentul regulament ori de câte ori este necesar.</p><h3 id="reguli-11" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-11" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toți membrii organizațiilor au obligația de a verifica periodic actualizările regulamentului.</li><li>Participarea într-o organizație criminală implică acceptarea tuturor prevederilor prezentului regulament.</li><li>Nerespectarea regulamentului poate atrage sancțiuni atât asupra membrilor, cât și asupra întregii organizații.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Respectarea prezentului regulament este obligatorie pentru toate organizațiile criminale din cadrul serverului <strong>Legacy Of CLT Roleplay</strong>.</p><p>Scopul acestui regulament este menținerea unui Roleplay realist, echilibrat și de calitate pentru întreaga comunitate.</p>',80)])])}const m=e(t,[["render",n]]);export{p as __pageData,m as default};
